import SwiftUI

// MARK: - Pet Vet art
//
// All Pet Vet art is vector shapes in App/Resources/Games/PetVet/petvet.json, generated by
// tools/petvet/build.py (animals.py, props.py). Colors are final hex values. Paths use M/L/C/Z
// only and are read with the same `PathParser` as the Dress Up art.

struct VetShape {
    let path: Path
    let fill: Color?
    let stroke: Color?
    let width: CGFloat
    let opacity: Double
}

struct VetAnimal {
    let id: String
    let back: [VetShape]
    let body: [VetShape]
    let front: [VetShape]
    let blush: [VetShape]
    let brows: [VetShape]
    let eyes: [String: [VetShape]]
    let mouths: [String: [VetShape]]
    let eye: CGPoint
    let mouth: CGPoint
}

struct VetToolArt {
    let shapes: [VetShape]
    let tip: CGPoint
    let tint: Color
}

final class VetArt {
    static let shared = VetArt()

    let patientSize: CGSize
    let roomSize: CGSize
    let anchors: [String: CGPoint]
    let order: [String]
    let animals: [String: VetAnimal]
    let props: [String: [VetShape]]
    let tools: [VetTool: VetToolArt]
    let rooms: [String: [VetShape]]

    private init() {
        var file: VetRawFile?
        if let url = GameFiles.url("petvet", "json", game: "PetVet"), let data = try? Data(contentsOf: url) {
            file = try? JSONDecoder().decode(VetRawFile.self, from: data)
        }
        guard let f = file else {
            patientSize = CGSize(width: 600, height: 660); roomSize = CGSize(width: 1400, height: 834)
            anchors = VetAnchors.all; order = []; animals = [:]; props = [:]; tools = [:]; rooms = [:]
            return
        }
        patientSize = CGSize(width: f.patient[0], height: f.patient[1])
        roomSize = CGSize(width: f.room[0], height: f.room[1])
        anchors = f.anchors.mapValues { CGPoint(x: $0[0], y: $0[1]) }
        order = f.order.filter { f.animals[$0] != nil }
        var a: [String: VetAnimal] = [:]
        for (id, r) in f.animals {
            a[id] = VetAnimal(
                id: id, back: r.back.map(VetArt.shape), body: r.body.map(VetArt.shape), front: r.front.map(VetArt.shape),
                blush: r.blush.map(VetArt.shape), brows: r.brows.map(VetArt.shape),
                eyes: r.eyes.mapValues { $0.map(VetArt.shape) }, mouths: r.mouths.mapValues { $0.map(VetArt.shape) },
                eye: CGPoint(x: r.eye[0], y: r.eye[1]), mouth: CGPoint(x: r.mouth[0], y: r.mouth[1]))
        }
        animals = a
        props = f.props.mapValues { $0.map(VetArt.shape) }
        var t: [VetTool: VetToolArt] = [:]
        for (id, r) in f.tools {
            guard let tool = VetTool(rawValue: id) else { continue }
            t[tool] = VetToolArt(shapes: r.shapes.map(VetArt.shape), tip: CGPoint(x: r.tip[0], y: r.tip[1]),
                                 tint: VetArt.color(r.tint) ?? .white)
        }
        tools = t
        rooms = f.rooms.mapValues { $0.map(VetArt.shape) }
    }

    static func color(_ s: String?) -> Color? {
        guard var h = s, !h.isEmpty else { return nil }
        if h.hasPrefix("#") { h.removeFirst() }
        guard let v = UInt32(h.prefix(6), radix: 16) else { return nil }
        return Color(hex: v)
    }

    private static func shape(_ r: VetRawShape) -> VetShape {
        VetShape(path: PathParser.parse(r.d), fill: color(r.f), stroke: color(r.s),
                 width: CGFloat(r.w ?? 4), opacity: r.o ?? 1)
    }
}

private struct VetRawShape: Decodable {
    let d: String
    let f: String?
    let s: String?
    let w: Double?
    let o: Double?
}

private struct VetRawAnimal: Decodable {
    let back, body, front, blush, brows: [VetRawShape]
    let eyes: [String: [VetRawShape]]
    let mouths: [String: [VetRawShape]]
    let eye: [Double]
    let mouth: [Double]
}

private struct VetRawTool: Decodable {
    let shapes: [VetRawShape]
    let tip: [Double]
    let tint: String
}

private struct VetRawFile: Decodable {
    let patient: [Double]
    let room: [Double]
    let anchors: [String: [Double]]
    let order: [String]
    let animals: [String: VetRawAnimal]
    let props: [String: [VetRawShape]]
    let tools: [String: VetRawTool]
    let rooms: [String: [VetRawShape]]
}

// MARK: - Drawing

enum VetDraw {
    static let heartScopeTreasureID = "petvet/heartScope"
    static let bowBandageTreasureID = "petvet/bowBandage"
    static var hasHeartScope: Bool { Coins.shared.owns(heartScopeTreasureID) }
    static var hasBowBandage: Bool { Coins.shared.owns(bowBandageTreasureID) }

    /// Draws shapes into `ctx`, which is already in art coordinates.
    static func shapes(_ list: [VetShape], in ctx: GraphicsContext, opacity: Double = 1) {
        for s in list {
            var g = ctx
            let o = s.opacity * opacity
            if o < 1 { g.opacity = o }
            if let f = s.fill { g.fill(s.path, with: .color(f)) }
            if let st = s.stroke {
                g.stroke(s.path, with: .color(st), style: StrokeStyle(lineWidth: s.width, lineCap: .round, lineJoin: .round))
            }
        }
    }

    /// Draws a named prop centered at `p`.
    static func prop(_ name: String, at p: CGPoint, scale: CGFloat = 1, rotation: Double = 0,
                     opacity: Double = 1, in ctx: GraphicsContext) {
        guard let list = VetArt.shared.props[name], opacity > 0.01, scale > 0.01 else { return }
        var g = ctx
        g.translateBy(x: p.x, y: p.y)
        if rotation != 0 { g.rotate(by: .degrees(rotation)) }
        g.scaleBy(x: scale, y: scale)
        shapes(list, in: g, opacity: opacity)
        if name == "bandage" && hasBowBandage {
            bowBandageAccent(in: g, opacity: opacity)
        }
    }

    /// Shiny pastel faceted heart-gem medallion for the upgraded stethoscope chestpiece.
    static func heartScopeMedallion(in ctx: GraphicsContext, at center: CGPoint) {
        var g = ctx
        g.translateBy(x: center.x, y: center.y)
        let goldEdge = StorybookArt.outline(for: 0xD9961E)

        let bezel = Path(ellipseIn: CGRect(x: -20, y: -20, width: 40, height: 40))
        g.fill(
            bezel,
            with: .radialGradient(
                Gradient(colors: [Color(hex: 0xFFF5B8), Color(hex: 0xFFCF4A), Color(hex: 0xDE981C)]),
                center: CGPoint(x: -5, y: -6),
                startRadius: 2,
                endRadius: 22
            )
        )
        g.stroke(bezel, with: .color(goldEdge), lineWidth: 2.8)
        g.stroke(Path(ellipseIn: CGRect(x: -16, y: -16, width: 32, height: 32)), with: .color(.white.opacity(0.6)), lineWidth: 1.4)

        let gem = VetExamView.heart(13.5)
        g.fill(
            gem,
            with: .linearGradient(
                Gradient(colors: [Color(hex: 0xFFB8DA), Color(hex: 0xFF6FA8), Color(hex: 0xC9B6FF)]),
                startPoint: CGPoint(x: -11, y: -12),
                endPoint: CGPoint(x: 11, y: 13)
            )
        )
        g.stroke(gem, with: .color(StorybookArt.outline(for: 0xE85792)), style: StrokeStyle(lineWidth: 2.2, lineJoin: .round))

        let facet = VetExamView.heart(7.2).applying(CGAffineTransform(translationX: 0, y: -1))
        g.fill(facet, with: .color(Color(hex: 0xFFE3F2, alpha: 0.72)))
        g.stroke(facet, with: .color(.white.opacity(0.85)), lineWidth: 1.2)
        StorybookArt.highlight(g, in: CGRect(x: -8.5, y: -7.5, width: 5.5, height: 3.6), opacity: 0.92)
        StorybookArt.sparkle(g, at: CGPoint(x: 14, y: -13), radius: 6, color: .white, opacity: 0.95)
        StorybookArt.sparkle(g, at: CGPoint(x: -15, y: 12), radius: 4.5, color: Theme.lemon, opacity: 0.9)
    }

    /// Cute pastel polka dots and a sweet satin ribbon bow perched atop applied bandages.
    static func bowBandageAccent(in ctx: GraphicsContext, opacity: Double = 1) {
        var g = ctx
        if opacity < 1 { g.opacity = opacity }
        g.rotate(by: .degrees(-20))

        let dots: [(CGFloat, CGFloat, Color)] = [
            (-39, -5.5, Theme.pink), (-31, 5.5, Theme.sky), (-24, -6.5, Theme.mint), (-36, 7.5, Theme.lemon), (-22, 6, Theme.lilac),
            (24, -6, Theme.lilac), (31, 6, Theme.mint), (39, -5.5, Theme.pink), (36, 7.5, Theme.sky), (23, 6.5, Theme.lemon),
        ]
        for (dx, dy, col) in dots {
            let dot = Path(ellipseIn: CGRect(x: dx - 3.2, y: dy - 3.2, width: 6.4, height: 6.4))
            g.fill(dot, with: .color(col))
            g.stroke(dot, with: .color(.white.opacity(0.7)), lineWidth: 0.9)
        }

        var bow = g
        bow.translateBy(x: 0, y: -13)
        satinBow(in: bow)
    }

    static func satinBow(in bow: GraphicsContext) {
        let ribbonFill = Color(hex: 0xFF8EC2)
        let ribbonShade = Color(hex: 0xF06BA8)
        let ribbonEdge = StorybookArt.outline(for: 0xE85792)

        for side in [-1.0, 1.0] {
            let s = CGFloat(side)
            var tail = Path()
            tail.move(to: CGPoint(x: s * 2, y: 2))
            tail.addQuadCurve(to: CGPoint(x: s * 14, y: 16), control: CGPoint(x: s * 11, y: 8))
            tail.addLine(to: CGPoint(x: s * 8, y: 13))
            tail.addLine(to: CGPoint(x: s * 4, y: 17))
            tail.closeSubpath()
            StorybookArt.fillAndStroke(bow, tail, fill: ribbonShade, stroke: ribbonEdge, width: 1.8)
        }

        for side in [-1.0, 1.0] {
            let s = CGFloat(side)
            var loop = Path()
            loop.move(to: .zero)
            loop.addCurve(to: CGPoint(x: s * 19, y: -10), control1: CGPoint(x: s * 6, y: -11), control2: CGPoint(x: s * 15, y: -15))
            loop.addCurve(to: CGPoint(x: s * 17, y: 7), control1: CGPoint(x: s * 23, y: -4), control2: CGPoint(x: s * 22, y: 5))
            loop.addCurve(to: .zero, control1: CGPoint(x: s * 11, y: 9), control2: CGPoint(x: s * 5, y: 5))
            loop.closeSubpath()
            StorybookArt.fillAndStroke(bow, loop, fill: ribbonFill, stroke: ribbonEdge, width: 2.1)
            StorybookArt.highlight(bow, in: CGRect(x: s < 0 ? -15 : 6, y: -8, width: 8.5, height: 4.5), opacity: 0.65)
        }

        let knot = Path(roundedRect: CGRect(x: -5.5, y: -5.5, width: 11, height: 11), cornerRadius: 5)
        StorybookArt.fillAndStroke(bow, knot, fill: Color(hex: 0xFFB8DA), stroke: ribbonEdge, width: 2)
        StorybookArt.highlight(bow, in: CGRect(x: -2.8, y: -3.5, width: 4, height: 2.5), opacity: 0.8)
    }

    /// Maps `box` into `size`, fitting and centering.
    static func fit(_ ctx: inout GraphicsContext, box: CGRect, into size: CGSize) {
        let s = min(size.width / box.width, size.height / box.height)
        ctx.translateBy(x: (size.width - box.width * s) / 2, y: (size.height - box.height * s) / 2)
        ctx.scaleBy(x: s, y: s)
        ctx.translateBy(x: -box.minX, y: -box.minY)
    }

    /// Fills `size` with a 1400 x 834 room, cropping the sides.
    static func room(_ name: String, size: CGSize, in ctx: GraphicsContext) {
        let art = VetArt.shared
        guard let list = art.rooms[name] else { return }
        var g = ctx
        let s = max(size.width / art.roomSize.width, size.height / art.roomSize.height)
        g.translateBy(x: (size.width - art.roomSize.width * s) / 2, y: (size.height - art.roomSize.height * s) / 2)
        g.scaleBy(x: s, y: s)
        shapes(list, in: g)
    }
}

/// What a patient's face shows.
struct VetFace: Equatable {
    var eyes: String
    var mouth: String
    var brows: Bool = false

    static let calm = VetFace(eyes: "open", mouth: "smile")
    static let sad = VetFace(eyes: "sad", mouth: "frown", brows: true)
    static let poorly = VetFace(eyes: "tired", mouth: "wavy", brows: true)
    static let ouch = VetFace(eyes: "wince", mouth: "ouch")
    static let giggle = VetFace(eyes: "happy", mouth: "grin")
    static let yum = VetFace(eyes: "happy", mouth: "yum")
    static let wow = VetFace(eyes: "sparkle", mouth: "grin")
    static let oh = VetFace(eyes: "open", mouth: "o")
    static let brushing = VetFace(eyes: "open", mouth: "wide")
    static let sneeze = VetFace(eyes: "wince", mouth: "o")
    static let blinkSmile = VetFace(eyes: "blink", mouth: "smile")
}

/// Draws one patient in its 600 x 660 art space. `overlay` draws on the body, under the face.
enum VetPatientPainter {
    static func draw(_ animal: VetAnimal, face: VetFace, look: CGVector = .zero, in ctx: GraphicsContext,
                     overlay: ((GraphicsContext) -> Void)? = nil, top: ((GraphicsContext) -> Void)? = nil) {
        VetDraw.shapes(animal.back, in: ctx)
        VetDraw.shapes(animal.body, in: ctx)
        overlay?(ctx)
        VetDraw.shapes(animal.front, in: ctx)
        VetDraw.shapes(animal.blush, in: ctx)
        var eyes = ctx
        if face.eyes == "open" || face.eyes == "sad" || face.eyes == "sparkle" {
            eyes.translateBy(x: look.dx, y: look.dy)
        }
        VetDraw.shapes(animal.eyes[face.eyes] ?? animal.eyes["open"] ?? [], in: eyes)
        if face.brows { VetDraw.shapes(animal.brows, in: ctx) }
        VetDraw.shapes(animal.mouths[face.mouth] ?? animal.mouths["smile"] ?? [], in: ctx)
        top?(ctx)
    }
}

/// A still picture of a patient (lobby seats, the drawer tile).
struct VetPatientPicture: View {
    let animal: String
    var face: VetFace = .calm
    var stickers: [VetSticker] = []

    var body: some View {
        Canvas { ctx, size in
            let art = VetArt.shared
            guard let a = art.animals[animal] else { return }
            var g = ctx
            VetDraw.fit(&g, box: CGRect(origin: .zero, size: art.patientSize), into: size)
            VetPatientPainter.draw(a, face: face, in: g, overlay: { c in
                for s in stickers { VetDraw.prop(s.prop, at: s.point, scale: s.scale, rotation: s.rotation, in: c) }
            })
        }
    }
}

/// One tool, drawn in its 140 x 140 box.
struct VetToolPicture: View {
    let tool: VetTool
    var body: some View {
        Canvas { ctx, size in
            guard let t = VetArt.shared.tools[tool] else { return }
            var g = ctx
            VetDraw.fit(&g, box: CGRect(x: 0, y: 0, width: 140, height: 140), into: size)
            VetDraw.shapes(t.shapes, in: g)
            if tool == .stethoscope && VetDraw.hasHeartScope {
                VetDraw.heartScopeMedallion(in: g, at: t.tip)
            } else if tool == .bandage && VetDraw.hasBowBandage {
                var bg = g
                bg.translateBy(x: t.tip.x, y: t.tip.y)
                bg.scaleBy(x: 1.1, y: 1.1)
                VetDraw.bowBandageAccent(in: bg)
            }
        }
    }
}

/// A prop drawn to fit a square.
struct VetPropPicture: View {
    let prop: String
    /// How many art units fit across the square.
    var units: CGFloat = 120
    var body: some View {
        Canvas { ctx, size in
            let s = min(size.width, size.height) / units
            VetDraw.prop(prop, at: CGPoint(x: size.width / 2, y: size.height / 2), scale: s, in: ctx)
        }
    }
}
